"""Browser page for the supervised, simulated payment demo."""

HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>掌纹支付演示</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#17212b;font:16px system-ui,sans-serif}header,main{max-width:1050px;margin:auto;padding:18px}header{display:flex;align-items:center;justify-content:space-between}h1{margin:0;font-size:1.6rem}h2{font-size:1.15rem}main{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(290px,1fr);gap:16px;padding-top:0}.card{background:white;border:1px solid #dce2e8;border-radius:12px;padding:18px}.preview{background:#111;aspect-ratio:4/3;border-radius:8px;overflow:hidden}.preview img{width:100%;height:100%;object-fit:contain}label{display:block;font-weight:600;margin:12px 0 5px}input,button{font:inherit}input{width:100%;padding:10px;border:1px solid #b9c4cc;border-radius:7px}button{border:0;border-radius:8px;padding:11px 15px;background:#125e9c;color:#fff;cursor:pointer;margin-top:12px}button:disabled{opacity:.5;cursor:wait}.secondary{background:#566b7a}.hint{font-size:.9rem;color:#526270;line-height:1.5}.notice{background:#eaf1f7;padding:12px;border-radius:8px;min-height:50px;white-space:pre-wrap;margin-top:12px}.candidate{background:#fff2d7;padding:14px;border-radius:8px;margin-top:12px}#roi{width:128px;height:128px;image-rendering:pixelated;background:#ddd}#roi[hidden],#candidate[hidden]{display:none}@media(max-width:760px){main{grid-template-columns:1fr}}</style></head><body>
<header><h1>掌纹支付 · 基础演示</h1><a href="/collect">高清采集页</a></header><main><section class="card"><h2>实时画面</h2><div class="preview"><img id="live" src="/frame.jpg" alt="相机画面"></div><p class="hint">把手掌放在画面中央，点击后拍一张 3280×2464 高清照片，从这张照片重新定位掌心。无需等待稳定提示，也不用移开手。</p><img id="roi" hidden alt="自动定位的掌心预览（匹配时会进一步对齐）"></section>
<section class="card"><h2>1. 录入</h2><label for="user">编号</label><input id="user" placeholder="例如 p01_left" pattern="[A-Za-z0-9_-]+"><label for="name">显示姓名</label><input id="name" placeholder="例如 演示用户 A"><button id="enroll">拍五张并录入 / 更新</button><div id="users" class="hint"></div><hr><h2>2. 模拟支付</h2><p>演示商品 · MOP 20.00</p><button id="identify">拍一张并识别</button><div id="candidate" class="candidate" hidden><strong id="candidate-name"></strong><p id="candidate-score" class="hint"></p><button id="confirm">确认姓名正确，模拟扣款</button> <button id="retry" class="secondary">姓名不对，重拍</button></div><div id="notice" class="notice">先录入，再拍照识别。</div><p class="hint">这是监督式演示；系统只给出候选身份，必须人工确认姓名才会模拟扣款。这里不代表真实支付安全性。</p></section></main>
<script>const $=id=>document.getElementById(id),notice=$('notice'),roi=$('roi');let busy=false,token='',candidateUser='';
async function preview(){try{const r=await fetch('/frame.jpg?t='+Date.now(),{cache:'no-store'});if(r.ok){const url=URL.createObjectURL(await r.blob()),old=$('live').src;$('live').src=url;if(old.startsWith('blob:'))$('live').onload=()=>URL.revokeObjectURL(old)}}catch(e){}setTimeout(preview,300)}preview();
function lock(value){busy=value;$('enroll').disabled=value;$('identify').disabled=value;$('confirm').disabled=value}
async function post(path,payload){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.message||'操作失败');return d}
async function users(){try{const r=await fetch('/api/demo/users');const d=await r.json();$('users').textContent=d.users.length?'已录入：'+d.users.map(x=>x.display_name+' ('+x.user_id+')'+(x.needs_reenrollment?' [需用原编号重新录入]':'')).join('、'):'尚未录入'}catch(e){$('users').textContent='暂时无法读取录入列表'}}users();
$('enroll').onclick=async()=>{const user=$('user').value.trim(),name=$('name').value.trim();if(!/^[A-Za-z0-9_-]{1,40}$/.test(user)||!name){notice.textContent='请填写编号和姓名。';return}lock(true);notice.textContent='正在连续拍摄五张高清照片，请将手留在画面中…';try{const d=await post('/api/demo/enroll',{user_id:user,display_name:name});notice.textContent=`已录入 ${d.display_name}。模拟余额 MOP ${(d.balance_cents/100).toFixed(2)}。`;await users()}catch(e){notice.textContent='录入失败：'+e.message}finally{lock(false)}};
$('identify').onclick=async()=>{lock(true);token='';roi.hidden=true;$('candidate').hidden=true;notice.textContent='正在拍摄高清照片并识别…';try{const d=await post('/api/demo/identify',{});if(d.roi_image){roi.src='data:image/png;base64,'+d.roi_image;roi.hidden=false}if(d.status==='MATCH'){token=d.token;candidateUser=d.user_id;$('candidate-name').textContent='候选身份：'+d.display_name;$('candidate-score').textContent='距离 '+d.score.toFixed(4)+(d.second_score==null?'':' · 第二名 '+d.second_score.toFixed(4));$('candidate').hidden=false;notice.textContent='请核对姓名；如果不对，点“姓名不对，重拍”。'}else notice.textContent=d.reason==='INCOMPATIBLE_TEMPLATES'?'录入资料需要更新，请用原编号重新录入；已有余额保留。':d.status==='UNKNOWN'?'未识别到已录入手掌；没有扣款。请调整位置后重拍。':'本次结果不明确；没有扣款。请重拍。'}catch(e){notice.textContent='识别失败：'+e.message}finally{lock(false)}};
$('retry').onclick=async()=>{const old=token;$('candidate').hidden=true;token='';if(old)try{await post('/api/demo/cancel',{token:old})}catch(e){}notice.textContent='已取消本次候选；没有扣款。请重拍。'};
$('confirm').onclick=async()=>{if(!token)return;lock(true);try{const d=await post('/api/demo/confirm',{token,user_id:candidateUser});$('candidate').hidden=true;token='';notice.textContent=d.status==='SUCCESS'?`模拟支付成功：${d.display_name}，MOP 20.00；余额 MOP ${(d.balance_cents/100).toFixed(2)}。`:'模拟支付未完成：'+d.status;await users()}catch(e){notice.textContent='没有扣款：'+e.message}finally{lock(false)}};
</script></body></html>"""
